SELECT PPCD, PWPL_NM AS PWPL_NM
  FROM GE_MP_PWPL_C
 WHERE PWPL_CFY = #{PWPL_CFY}

		SELECT TST_UNQ_KY_VAL, FRM_CFY, RELTN_SCTN_NM, MSG_CTT, REGPR_ID, REGPR_NM, RG_DT
		  FROM GE_MP_MSGE_S
		 WHERE TST_UNQ_KY_VAL = #{TST_UNQ_KY_VAL}
		   AND FRM_CFY = #{FRM_CFY}
      ORDER BY RG_DT ASC
